Q: Counting instances of genotype strings where order is irrelevant within locus A: <p>To treat <em>Xx</em> and <em>xX</em> as the same we might use a <code>strsplit</code>/<code>sort</code> approach, but on <code>factor</code> levels for sake of efficiency. This assumes diploid, biallelic loci.</p>
<pre><code>canonicalize_genotype &lt;- \(x, decreasing.=TRUE) {
  base_levels &lt;- \(A) {
    strsplit(A, '') |&gt; 
      lapply(sort.int, decreasing=decreasing.) |&gt; 
      sapply(paste, collapse='')
  } 
  x &lt;- unlist(x)
  len &lt;- nchar(x)
  if (var(len) != 0) {
    stop('lengths ambiguous.')
  } else {
    len &lt;- el(len)
  }
  a &lt;- vapply(seq_len(len/2) - 1, \(i) {
    substr(x, 1 + 2*i, 2 + 2*i)
  }, FUN.VALUE=character(length(x))) |&gt; 
    as.factor()
  starts &lt;- seq(1L, len, by=2L)
  ends &lt;- starts+1L
  substring(x, starts, ends)
  levels(a) &lt;- base_levels(levels(a))
  matrix(a, ncol=len/2) |&gt;
    as.data.frame() |&gt;
    Reduce(f=paste0)
}
</code></pre>
<p><em>Gives:</em></p>
<pre><code>&gt; canonicalize_genotype(offspring) |&gt; 
+   table()

aabb aaBb aaBB Aabb AaBb AaBB AAbb AABb AABB 
   1    2    1    2    4    2    1    2    1 
</code></pre>
<p><strong>Notice</strong> that the table displays <em>Xx</em> rather than <em>xX</em>, as the OP seems to prefer. To get <em>xX</em>, use <code>canonicalize_genotype(., decreasing.=FALSE)</code>.</p>
<p>I wrote it so it generalizes to more than two loci <em>[[aa, aA, Aa, AA], [bb, bB, Bb, BB], [cc, cC, Cc, CC], ...]</em>:</p>
<pre><code>&gt; offspring3 |&gt; canonicalize_genotype() |&gt; table()

aabbcc aabbCc aabbCC aaBbcc aaBbCc aaBbCC aaBBcc aaBBCc aaBBCC Aabbcc AabbCc AabbCC AaBbcc AaBbCc AaBbCC 
     1      2      1      2      4      2      1      2      1      2      4      2      4      8      4 
AaBBcc AaBBCc AaBBCC AAbbcc AAbbCc AAbbCC AABbcc AABbCc AABbCC AABBcc AABBCc AABBCC 
     2      4      2      1      2      1      2      4      2      1      2      1 
</code></pre>
<hr />
<p><em>Data:</em></p>
<pre><code>mk_mat &lt;- \(m, n) {
  replicate(m*m, lapply(seq_len(n), \(i) {
    sample(c(letters[i], LETTERS[i]), replace=TRUE) |&gt; 
      paste(collapse='')
  }), simplify=FALSE) |&gt; 
    sapply(paste, collapse='') |&gt; 
    matrix(m, m)
}

set.seed(42)
df &lt;- mk_mat(4, 3) |&gt; 
  as.data.frame()


mk_punnet &lt;- \(nloci) {
  m &lt;- matrix(as.logical(intToBits(0:(2^nloci - 1))), ncol=32, byrow=TRUE)
  loci &lt;- t(replicate(2^nloci, LETTERS[seq_len(nloci)]))
  loci[m[, nloci:1]] &lt;- tolower(loci[m[, nloci:1]])
  aloci &lt;- asplit(loci, 1)
  outer(aloci, aloci, Vectorize(\(a, b) paste0(a, b, collapse=''))) |&gt;
    `dimnames&lt;-`(
      replicate(2, 
                apply(loci, 1, paste, collapse=''), 
                simplify=FALSE)
    ) |&gt;
    as.data.frame()
}

offspring3 &lt;- mk_punnet(nloci=3)
</code></pre>
<p><em>Giving:</em></p>
<pre><code>&gt; offspring3
       ABC    ABc    AbC    Abc    aBC    aBc    abC    abc
ABC AABBCC AABBCc AABbCC AABbCc AaBBCC AaBBCc AaBbCC AaBbCc
ABc AABBcC AABBcc AABbcC AABbcc AaBBcC AaBBcc AaBbcC AaBbcc
AbC AAbBCC AAbBCc AAbbCC AAbbCc AabBCC AabBCc AabbCC AabbCc
Abc AAbBcC AAbBcc AAbbcC AAbbcc AabBcC AabBcc AabbcC Aabbcc
aBC aABBCC aABBCc aABbCC aABbCc aaBBCC aaBBCc aaBbCC aaBbCc
aBc aABBcC aABBcc aABbcC aABbcc aaBBcC aaBBcc aaBbcC aaBbcc
abC aAbBCC aAbBCc aAbbCC aAbbCc aabBCC aabBCc aabbCC aabbCc
abc aAbBcC aAbBcc aAbbcC aAbbcc aabBcC aabBcc aabbcC aabbcc
</code></pre>

Q: How do I get the formula separator in a script? A: <blockquote>
<p>is there a way to get whether I should put a <code>,</code> or a <code>;</code>?</p>
</blockquote>
<p>yes, you can use this universal formula:</p>
<pre class="lang-jsx prettyprint-override"><code>=INDEX(VLOOKUP(MID(FORMULATEXT(INDIRECT(ADDRESS(ROW(); COLUMN()))); 54; 1); 
 SUBSTITUTE(SUBSTITUTE(SPLIT({
 &quot;,♣,♦fx argument separator♠;♦array column stacking♠,♦array row stacking♠.♦decimal separator&quot;;
 &quot;;♣;♦fx argument separator♠;♦array column stacking♠\♦array row stacking♠,♦decimal separator&quot;}; 
 &quot;♣&quot;); &quot;♠&quot;; CHAR(10)); &quot;♦&quot;; &quot;     &quot;); 2; IFERROR(NOW()/0)))
</code></pre>
